css:
/* Wrapper label — clickable, flex row */
.retro-toggle {
  display: inline-flex;
  align-items: center;
  gap: 1rem;
  cursor: pointer;
  user-select: none;
  font-family: "Courier New", Courier, monospace;
}

/* Hide the real checkbox */
.retro-toggle input[type="checkbox"] {
  display: none;
}

/* ── Text label using ::before content trick ── */
.retro-label {
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: #1f2937;
  text-shadow: 1px 1px 0 rgba(255, 255, 255, 0.8);
}

/* Default (OFF) label text */
.retro-label::before {
  content: attr(data-off);
}

/* ON state label text */
.retro-toggle input:checked ~ .retro-label::before {
  content: attr(data-on);
}

/* ── Track (outer shell) ── */
.retro-track {
  position: relative;
  width: 6rem; /* 96px */
  height: 3rem; /* 48px */
  background: #9ca3af;
  border-radius: 2px;
  border-top: 4px solid #ffffff;
  border-left: 4px solid #ffffff;
  border-right: 4px solid #000000;
  border-bottom: 4px solid #000000;
  box-shadow: inset 4px 4px 0 rgba(0, 0, 0, 0.2);
  padding: 4px;
}

/* ── Thumb (sliding knob) ── */
.retro-thumb {
  position: absolute;
  top: 4px;
  left: 4px;
  width: 2rem; /* 32px */
  height: calc(100% - 8px);
  background: #e5e7eb;
  border-top: 2px solid #ffffff;
  border-left: 2px solid #ffffff;
  border-right: 2px solid #000000;
  border-bottom: 2px solid #000000;
  box-shadow: 2px 2px 0 rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: left 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* Thumb slides right when checked */
.retro-toggle input:checked ~ .retro-track .retro-thumb {
  left: calc(100% - 2rem - 4px);
}

/* ── Power SVG icon ── */
.power-icon {
  width: 16px;
  height: 16px;
  stroke-width: 2;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke: #dc2626; /* red = OFF */
  transition: stroke 0.2s;
}

/* Icon turns green when ON */
.retro-toggle input:checked ~ .retro-track .power-icon {
  stroke: #16a34a;
}
